//! THE RGD SURFACE — a `ResourceGraphDefinition` parsed off the wire
//! (`serde_json::Value`, the face currency) into typed structs, with the
//! naming/grammar validations the CRD schema cannot express (reserved
//! words, the id grammar, template-or-ref exclusivity at the leaf level).

use serde_json::Value as Json;
use std::collections::BTreeMap;

/// Typed identity of an RGD — generated by `#[derive(krapi_rgd::Rgd)]`.
/// Replaces stringly-typed kind/plural/group names at every call site.
pub trait RgdKind {
    /// The instance kind (e.g. `Function`).
    fn kind() -> &'static str;
    /// The instance plural (e.g. `functions`).
    fn plural_name() -> &'static str;
    /// The API group (e.g. `kapi.qreta.io`).
    fn group() -> &'static str;
    /// The RGD manifest name (e.g. `function`).
    fn name() -> &'static str;
}

/// The lowerCamelCase id grammar (CEL identifiers cannot carry `-`).
pub const ID_PATTERN: &str = "^[a-z][a-zA-Z0-9]*$";
/// The instance kind grammar.
pub const KIND_PATTERN: &str = "^[A-Z][a-zA-Z0-9]{0,62}$";
/// The instance version grammar.
pub const API_VERSION_PATTERN: &str = "^v[0-9]+(alpha[0-9]+|beta[0-9]+)?$";
/// The instance group grammar (DNS subdomain).
pub const GROUP_PATTERN: &str = "^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$";
/// The plural override grammar (DNS label).
pub const PLURAL_PATTERN: &str = "^[a-z]([-a-z0-9]*[a-z0-9])?$";

/// CEL reserved symbols + kro's own reserved words — no resource id may
/// collide (an id named `true` or `each` would corrupt every expression).
const RESERVED: &[&str] = &[
    "true",
    "false",
    "null",
    "in",
    "as",
    "break",
    "const",
    "continue",
    "else",
    "for",
    "function",
    "if",
    "import",
    "let",
    "loop",
    "package",
    "namespace",
    "return",
    "var",
    "void",
    "while",
    "schema",
    "each",
    "runtime",
    "instance",
    "metadata",
    "kind",
    "apiVersion",
    "context",
    "dependency",
    "dependencies",
    "item",
    "items",
    "kro",
    "kro_rs",
    "self",
    "oldSelf",
    "params",
    "request",
];

/// The parsed `ResourceGraphDefinition`.
#[derive(Debug, Clone)]
pub struct ResourceGraphDefinition {
    /// metadata.name.
    pub name: String,
    /// metadata.uid (the ownership join for children).
    pub uid: String,
    /// metadata.generation.
    pub generation: u64,
    pub spec: RgdSpec,
}

/// The RGD spec.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RgdSpec {
    pub schema: Schema,
    pub resources: Vec<Resource>,
}

/// The instance schema block.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Schema {
    pub kind: String,
    /// The plural override; None derives from the kind.
    pub plural: Option<String>,
    pub api_version: String,
    /// The instance CRD's group; None uses the engine default.
    pub group: Option<String>,
    /// Namespaced (default) or Cluster.
    pub scope: Scope,
    /// The `SimpleSchema` spec body (a map).
    pub spec: BTreeMap<String, Json>,
    /// Custom type definitions referenced by the spec.
    pub types: BTreeMap<String, Json>,
    /// The status projection body: field → `${...}` expressions (plus the
    /// `conditions` block, a list of expression strings).
    pub status: BTreeMap<String, Json>,
    /// The metadata.name validation markers, when set.
    pub name_validation: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
pub enum Scope {
    Namespaced,
    Cluster,
}

/// One resource in the graph.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Resource {
    pub id: String,
    /// The user's list position — the topological order's tie-breaker.
    pub order: usize,
    pub template: Option<Json>,
    pub external_ref: Option<ExternalRef>,
    /// `readyWhen` — unwrapped CEL (must all hold for readiness).
    pub ready_when: Vec<String>,
    /// `includeWhen` — unwrapped CEL (must all hold to include the node).
    pub include_when: Vec<String>,
    /// `forEach` — `(iterator name, unwrapped CEL producing a list)`.
    #[serde(serialize_with = "serialize_for_each")]
    pub for_each: Vec<(String, String)>,
}

/// A read-only reference to an existing resource.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ExternalRef {
    pub api_version: String,
    pub kind: String,
    /// None = same namespace as the instance (namespaced kinds) /
    /// cluster-scoped lookup.
    pub namespace: Option<String>,
    pub name: Option<String>,
}

/// The id grammar check (`a`, `webApp`, never `web-app`).
#[must_use]
pub fn valid_id(id: &str) -> bool {
    let mut chars = id.chars();
    match chars.next() {
        Some('a'..='z') => {}
        _ => return false,
    }
    let rest: String = chars.collect();
    rest.chars().all(|c| c.is_ascii_alphanumeric())
}

/// The kind grammar check.
#[must_use]
pub fn valid_kind(kind: &str) -> bool {
    let mut chars = kind.chars();
    match chars.next() {
        Some('A'..='Z') => {}
        _ => return false,
    }
    let rest: String = chars.collect();
    rest.len() <= 62 && rest.chars().all(|c| c.is_ascii_alphanumeric())
}

/// The version grammar check (`v1`, `v1alpha1`, `v2beta1`).
#[must_use]
pub fn valid_api_version(v: &str) -> bool {
    let Some(rest) = v.strip_prefix('v') else {
        return false;
    };
    let (num, tail) = split_at_first_non_digit(rest);
    if num.is_empty() {
        return false;
    }
    tail.is_empty()
        || tail
            .strip_prefix("alpha")
            .is_some_and(|t| all_digits(t) && !t.is_empty())
        || tail
            .strip_prefix("beta")
            .is_some_and(|t| all_digits(t) && !t.is_empty())
}

fn split_at_first_non_digit(s: &str) -> (&str, &str) {
    let idx = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
    (&s[..idx], &s[idx..])
}

fn all_digits(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

/// The reserved-word check.
#[must_use]
pub fn reserved(id: &str) -> bool {
    RESERVED.contains(&id)
}

/// Parse one RGD body.
///
/// # Errors
/// Any structural refusal — missing schema, bad names, unknown resource
/// shapes, unwrapped policy expressions.
#[allow(clippy::too_many_lines)] // the wire grammar reads best in one pass
pub fn parse(body: &Json, default_group: &str) -> Result<ResourceGraphDefinition, String> {
    let name = str_at(body, "/metadata/name")
        .ok_or("metadata.name is required")?
        .to_owned();
    let uid = str_at(body, "/metadata/uid").unwrap_or_default().to_owned();
    let generation = body
        .pointer("/metadata/generation")
        .and_then(Json::as_u64)
        .unwrap_or(1);
    let spec = body
        .get("spec")
        .and_then(Json::as_object)
        .ok_or("spec is required")?;

    let schema = spec
        .get("schema")
        .and_then(Json::as_object)
        .ok_or("spec.schema is required")?;
    let kind = schema
        .get("kind")
        .and_then(Json::as_str)
        .ok_or("spec.schema.kind is required")?;
    if !valid_kind(kind) {
        return Err(format!(
            "spec.schema.kind {kind:?} must match {KIND_PATTERN}"
        ));
    }
    let plural = schema
        .get("plural")
        .and_then(Json::as_str)
        .map(str::to_owned);
    if let Some(p) = &plural
        && !p.chars().next().is_some_and(|c| c.is_ascii_lowercase())
    {
        return Err(format!(
            "spec.schema.plural {p:?} must match {PLURAL_PATTERN}"
        ));
    }
    let api_version = schema
        .get("apiVersion")
        .and_then(Json::as_str)
        .ok_or("spec.schema.apiVersion is required")?;
    if !valid_api_version(api_version) {
        return Err(format!(
            "spec.schema.apiVersion {api_version:?} must match {API_VERSION_PATTERN}"
        ));
    }
    let group = schema
        .get("group")
        .and_then(Json::as_str)
        .map(str::to_owned)
        .or_else(|| {
            if default_group.is_empty() {
                None
            } else {
                Some(default_group.to_owned())
            }
        });
    let scope = match schema.get("scope").and_then(Json::as_str) {
        None | Some("Namespaced") => Scope::Namespaced,
        Some("Cluster") => Scope::Cluster,
        Some(other) => {
            return Err(format!(
                "spec.schema.scope {other:?} must be Namespaced or Cluster"
            ));
        }
    };
    let spec_body = object_map(schema.get("spec"), "spec.schema.spec")?;
    let types_body = object_map(schema.get("types"), "spec.schema.types")?;
    let status_body = object_map(schema.get("status"), "spec.schema.status")?;
    let name_validation = schema
        .get("metadata")
        .and_then(|m| m.get("validation"))
        .and_then(|v| v.get("name"))
        .and_then(Json::as_str)
        .map(str::to_owned);

    let resources_in = spec
        .get("resources")
        .and_then(Json::as_array)
        .ok_or("spec.resources is required")?;
    if resources_in.is_empty() {
        return Err("spec.resources must carry at least one resource".to_owned());
    }
    let mut resources = Vec::with_capacity(resources_in.len());
    let mut seen = std::collections::BTreeSet::new();
    for (i, r) in resources_in.iter().enumerate() {
        let id = str_at(r, "/id").ok_or_else(|| format!("resources[{i}].id is required"))?;
        if !valid_id(id) {
            return Err(format!(
                "resources[{i}].id {id:?} must match {ID_PATTERN} (CEL identifiers cannot carry hyphens)"
            ));
        }
        if reserved(id) {
            return Err(format!("resources[{i}].id {id:?} is a reserved word"));
        }
        if !seen.insert(id.to_owned()) {
            return Err(format!("duplicate resource id {id:?}"));
        }
        let template = r.get("template").filter(|t| !t.is_null());
        let ext = r.get("externalRef").filter(|t| !t.is_null());
        match (template.is_some(), ext.is_some()) {
            (true, true) => {
                return Err(format!(
                    "resources[{i}] ({id}): template and externalRef are mutually exclusive"
                ));
            }
            (false, false) => {
                return Err(format!(
                    "resources[{i}] ({id}): exactly one of template or externalRef is required"
                ));
            }
            _ => {}
        }
        let external_ref = ext.map(|e| ExternalRef {
            api_version: str_at(e, "/apiVersion").unwrap_or_default().to_owned(),
            kind: str_at(e, "/kind").unwrap_or_default().to_owned(),
            namespace: str_at(e, "/metadata/namespace").map(str::to_owned),
            name: str_at(e, "/metadata/name").map(str::to_owned),
        });
        let ready_when = string_list(r.get("readyWhen"), id, "readyWhen")?
            .into_iter()
            .map(|s| crate::expression::unwrap(&s))
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| format!("resources[{i}] ({id}) readyWhen: {e}"))?;
        let include_when = string_list(r.get("includeWhen"), id, "includeWhen")?
            .into_iter()
            .map(|s| crate::expression::unwrap(&s))
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| format!("resources[{i}] ({id}) includeWhen: {e}"))?;
        let for_each_in = r
            .get("forEach")
            .and_then(Json::as_array)
            .map_or_else(Vec::new, std::vec::Vec::clone);
        let mut for_each = Vec::new();
        for (di, d) in for_each_in.iter().enumerate() {
            let obj = d
                .as_object()
                .ok_or_else(|| format!("resources[{i}] ({id}) forEach[{di}] must be an object"))?;
            if obj.len() != 1 {
                return Err(format!(
                    "resources[{i}] ({id}) forEach[{di}] must carry exactly one name: expression entry"
                ));
            }
            for (name, expr) in obj {
                if !valid_id(name) {
                    return Err(format!(
                        "resources[{i}] ({id}) forEach[{di}] name {name:?} must match {ID_PATTERN}"
                    ));
                }
                let expr = crate::expression::unwrap(expr.as_str().ok_or_else(|| {
                    format!("resources[{i}] ({id}) forEach[{di}].{name} must be a ${{...}} string")
                })?)
                .map_err(|e| format!("resources[{i}] ({id}) forEach[{di}]: {e}"))?;
                for_each.push((name.clone(), expr));
            }
        }
        resources.push(Resource {
            id: id.to_owned(),
            order: i,
            template: template.cloned(),
            external_ref,
            ready_when,
            include_when,
            for_each,
        });
    }

    Ok(ResourceGraphDefinition {
        name,
        uid,
        generation,
        spec: RgdSpec {
            schema: Schema {
                kind: kind.to_owned(),
                plural,
                api_version: api_version.to_owned(),
                group,
                scope,
                spec: spec_body,
                types: types_body,
                status: status_body,
                name_validation,
            },
            resources,
        },
    })
}

fn str_at<'a>(v: &'a Json, pointer: &str) -> Option<&'a str> {
    v.pointer(pointer).and_then(Json::as_str)
}

fn object_map(v: Option<&Json>, what: &str) -> Result<BTreeMap<String, Json>, String> {
    match v {
        None | Some(Json::Null) => Ok(BTreeMap::new()),
        Some(Json::Object(map)) => Ok(map
            .iter()
            .map(|(k, val)| (k.clone(), val.clone()))
            .collect()),
        Some(other) => Err(format!("{what} must be an object, got: {other}")),
    }
}

fn string_list(v: Option<&Json>, id: &str, what: &str) -> Result<Vec<String>, String> {
    match v {
        None | Some(Json::Null) => Ok(Vec::new()),
        Some(Json::Array(items)) => items
            .iter()
            .map(|x| {
                x.as_str()
                    .map(str::to_owned)
                    .ok_or_else(|| format!("resource {id}: {what} entries must be strings"))
            })
            .collect(),
        Some(other) => Err(format!(
            "resource {id}: {what} must be a list, got: {other}"
        )),
    }
}

/// Derive the plural from the kind (lowercase; simple English rules with
/// the s/x/z/ch/sh → es and consonant+y → ies cases).
#[must_use]
pub fn pluralize(kind: &str) -> String {
    let lower = kind.to_ascii_lowercase();
    if let Some(p) = lower
        .strip_suffix('y')
        .filter(|s| !s.is_empty() && !matches!(s.chars().last(), Some('a' | 'e' | 'i' | 'o' | 'u')))
    {
        return format!("{p}ies");
    }
    if lower
        .chars()
        .last()
        .is_some_and(|c| "sxz".contains(c) || lower.ends_with("ch") || lower.ends_with("sh"))
    {
        return format!("{lower}es");
    }
    format!("{lower}s")
}

/// Serialize `forEach` pairs as `{name: expression}` objects (kro grammar).
fn serialize_for_each<S>(entries: &[(String, String)], ser: S) -> Result<S::Ok, S::Error>
where
    S: serde::Serializer,
{
    use serde::ser::SerializeSeq;
    let mut seq = ser.serialize_seq(Some(entries.len()))?;
    for (name, expr) in entries {
        let mut map = ::std::collections::BTreeMap::new();
        map.insert(name, expr);
        seq.serialize_element(&map)?;
    }
    seq.end()
}
#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn rgd() -> Json {
        json!({
            "metadata": {"name": "webstore", "uid": "u1", "generation": 1},
            "spec": {
                "schema": {
                    "apiVersion": "v1alpha1",
                    "kind": "WebStore",
                    "spec": {"name": "string | required=true"},
                    "status": {}
                },
                "resources": [
                    {"id": "configmap", "template": {"apiVersion": "v1", "kind": "ConfigMap",
                        "metadata": {"name": "${schema.spec.name}--cm"}}}
                ]
            }
        })
    }

    #[test]
    fn a_valid_rgd_parses() {
        let rgd = parse(&rgd(), "kro.rs").unwrap();
        assert_eq!(rgd.name, "webstore");
        assert_eq!(rgd.spec.schema.kind, "WebStore");
        assert_eq!(rgd.spec.schema.group.as_deref(), Some("kro.rs"));
        assert_eq!(rgd.spec.resources[0].id, "configmap");
        assert_eq!(rgd.spec.resources[0].order, 0);
    }

    #[test]
    fn grammar_refusals() {
        let mut bad = rgd();
        bad["spec"]["schema"]["kind"] = json!("webStore");
        assert!(parse(&bad, "kro.rs").is_err());
        let mut bad = rgd();
        bad["spec"]["schema"]["apiVersion"] = json!("v1-alpha");
        assert!(parse(&bad, "kro.rs").is_err());
        let mut bad = rgd();
        bad["spec"]["resources"][0]["id"] = json!("web-cm");
        assert!(parse(&bad, "kro.rs").is_err());
    }

    #[test]
    fn reserved_and_duplicate_ids_refuse() {
        let mut bad = rgd();
        bad["spec"]["resources"][0]["id"] = json!("each");
        assert!(parse(&bad, "kro.rs").is_err());
        let mut bad = rgd();
        let first = bad["spec"]["resources"][0].clone();
        bad["spec"]["resources"]
            .as_array_mut()
            .expect("resources is an array")
            .push(first);
        let idx = bad["spec"]["resources"].as_array().expect("array").len() - 1;
        bad["spec"]["resources"][idx]["template"]["metadata"]["name"] = json!("other");
        assert!(parse(&bad, "kro.rs").is_err());
    }

    #[test]
    fn template_and_external_ref_are_exclusive() {
        let mut bad = rgd();
        bad["spec"]["resources"][0]["externalRef"] =
            json!({"apiVersion": "v1", "kind": "ConfigMap", "metadata": {"name": "x"}});
        assert!(parse(&bad, "kro.rs").is_err());
        let mut bad = rgd();
        bad["spec"]["resources"][0]["template"] = Json::Null;
        assert!(parse(&bad, "kro.rs").is_err());
    }

    #[test]
    fn policy_expressions_must_be_wrapped() {
        let mut bad = rgd();
        bad["spec"]["resources"][0]["readyWhen"] = json!(["configmap.data.ready == \"true\""]);
        let err = parse(&bad, "kro.rs").unwrap_err();
        assert!(err.contains("readyWhen"), "{err}");
    }

    #[test]
    fn pluralize_english_rules() {
        assert_eq!(pluralize("WebStore"), "webstores");
        assert_eq!(pluralize("PodPolicy"), "podpolicies");
        assert_eq!(pluralize("Bus"), "buses");
        assert_eq!(pluralize("Box"), "boxes");
    }
}
